mapper.select:
select hit.userId, min(hit.applicationId) as applicationId from (
select u.user_id as userId, null as applicationId from sys_user u where u.user_id = #{numericId} and u.user_type = '10' and u.status = '0' and u.del_flag = '0' union all select acc.user_id as userId, app.id as applicationId from nad_application app join nad_user_applicant_access acc on acc.applicant_id = app.applicant_id and acc.status = 'ACTIVE' join sys_user u on u.user_id = acc.user_id and u.user_type = '10' and u.status = '0' and u.del_flag = '0' where app.id = #{numericId} union all
select u.user_id as userId, null as applicationId from sys_user u where u.user_type = '10' and u.status = '0' and u.del_flag = '0' and (u.nick_name like concat('%', #{text}, '%') or u.user_name like concat('%', #{text}, '%') or exists (select 1 from nad_user_applicant_access acc join nad_applicant a on a.id = acc.applicant_id where acc.user_id = u.user_id and acc.status = 'ACTIVE' and (a.given_name like concat(#{text}, '%') or a.family_name like concat(#{text}, '%')))) ) hit group by hit.userId order by min(case when hit.applicationId is not null then 0 else 1 end), hit.userId limit #{limit}
